// Runs once for ALL fetched records and builds ONE report. Each record has a
// name, a type and an ISO expiry date ("expires"); rename the keys to match
// your API. Rows are grouped by urgency and color-coded.
const DAY = 24 * 60 * 60 * 1000;
const today = new Date();
today.setUTCHours(0, 0, 0, 0);

const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const status = (days) =>
  days < 0 ? ['Expired', '#c62828'] :
  days <= 7 ? ['Within 7 days', '#ef6c00'] :
  days <= 30 ? ['Within 30 days', '#f9a825'] : null;

const rows = $input.all()
  .map(({ json }) => ({ ...json, days: Math.floor((new Date(json.expires) - today) / DAY) }))
  .filter((r) => !Number.isNaN(r.days) && status(r.days))
  .sort((a, b) => a.days - b.days);

const body = rows.length
  ? rows.map((r) => {
      const [label, color] = status(r.days);
      return `<tr><td>${esc(r.name)}</td><td>${esc(r.type)}</td><td>${esc(r.expires)}</td>` +
        `<td><span class="dot" style="background:${color}"></span>${label}</td></tr>`;
    }).join('\n')
  : '<tr><td colspan="4">Nothing expires in the next 30 days.</td></tr>';

const date = today.toISOString().slice(0, 10);
const html = `<!doctype html>
<html><head><meta charset="utf-8"><style>
@page { size: A4 landscape; margin: 15mm;
  @top-right { content: "Expiry report ${date}"; font: 8pt sans-serif; color: #6b7480 }
  @bottom-center { content: "Page " counter(page) " of " counter(pages); font: 8pt sans-serif; color: #6b7480 } }
body { font: 10pt/1.45 "DejaVu Sans", sans-serif; color: #1c2024 }
table { width: 100%; border-collapse: collapse }
th { text-align: left; border-bottom: 2px solid #1c2024; padding: 2mm 0 }
td { padding: 2mm 0; border-bottom: 1px solid #e3e6ea }
thead { display: table-header-group }
tr { break-inside: avoid }
.dot { display: inline-block; width: 3mm; height: 3mm; border-radius: 50%; margin-right: 2mm }
</style></head><body>
<h1>Expiry report</h1>
<p>${date} · ${rows.length} item(s) expired or due within 30 days</p>
<table>
  <thead><tr><th>Name</th><th>Type</th><th>Expires</th><th>Status</th></tr></thead>
  <tbody>
${body}
  </tbody>
</table>
</body></html>`;

return [{ json: { html, filename: `expiry-report-${date}.pdf`, count: rows.length, date } }];
